WHERE true
AND (o.create_by = #{scope.userId} OR o.buyer_id = #{scope.userId})

    AND o.status IN #{s}

AND o.purchase_type = #{q.purchaseType}
AND o.supplier_id = #{q.supplierId}
AND o.buyer_id = #{q.buyerId}
AND o.order_date >= #{q.orderDateFrom}
AND o.order_date <= #{q.orderDateTo}

    AND o.id IN #{id}


    AND (o.no ILIKE '%' || #{q.keyword} || '%' OR s.name ILIKE '%' || #{q.keyword} || '%'
         OR s.short_name ILIKE '%' || #{q.keyword} || '%'

             OR upper(o.no) IN #{code}

         OR EXISTS (SELECT 1 FROM pur_order_item i WHERE i.purchase_order_id = o.id AND ()))

mapper.select:
SELECT i.id AS purchase_item_id, o.id AS purchase_order_id, o.no AS purchase_no, o.purchase_type, o.supplier_id, s.short_name AS supplier_name, o.buyer_id, o.warehouse_id, w.name AS warehouse_name, i.material_sku_id, i.purchase_unit, i.qty, i.received_qty, i.returned_qty, COALESCE(i.line_due_date, o.delivery_date) AS due_date, i.expect_date, i.follow_note, i.calc_item_id, o.create_by FROM pur_order_item i JOIN pur_order o ON o.id = i.purchase_order_id JOIN sup_supplier s ON s.id = o.supplier_id JOIN bas_warehouse w ON w.id = o.warehouse_id WHERE o.status IN ('APPROVED', 'RUNNING') AND i.received_qty - i.returned_qty < i.qty AND (o.create_by = #{scope.userId} OR o.buyer_id = #{scope.userId}) AND o.supplier_id = #{q.supplierId} AND o.buyer_id = #{q.buyerId} AND COALESCE(i.line_due_date, o.delivery_date) >= #{q.dueDateFrom} AND COALESCE(i.line_due_date, o.delivery_date) <= #{q.dueDateTo}
AND (o.no ILIKE '%' || #{q.keyword} || '%' OR s.name ILIKE '%' || #{q.keyword} || '%' OR s.short_name ILIKE '%' || #{q.keyword} || '%'
OR upper(o.no) IN #{code}
OR )
